static size_t FindUnquotedJsonChar(const std::string& content, size_t from, char target) {
    bool inString = false;
    for (size_t i = from; i < content.size(); ++i) {
        char c = content[i];
        if (inString) {
            if (c == '\\') { ++i; continue; }
            if (c == '"') inString = false;
            continue;
        }
        if (c == '"') { inString = true; continue; }
        if (c == target) return i;
    }
    return std::string::npos;
}

// Fish/Void/Bloxstrap integration
std::string GetBloxstrapSettingsPath() {
    HKEY hKey;
    if (RegOpenKeyExW(HKEY_CLASSES_ROOT, L"roblox-player\\DefaultIcon", 0, KEY_READ | KEY_WOW64_64KEY, &hKey) != ERROR_SUCCESS) {
        return "";
    }

wchar_t value[MAX_PATH + 1] = { 0 };
DWORD size = sizeof(value) - sizeof(wchar_t);
if (RegQueryValueExW(hKey, NULL, NULL, NULL, (LPBYTE)value, &size) != ERROR_SUCCESS) {
RegCloseKey(hKey);
return "";
}
RegCloseKey(hKey);
value[MAX_PATH] = L'\0';

std::wstring path_w(value);
    std::wstring exe_path_w;

    size_t first_quote = path_w.find(L'"');
    if (first_quote == 0) {
        size_t second_quote = path_w.find(L'"', first_quote + 1);
        if (second_quote == std::wstring::npos) { return ""; }
        exe_path_w = path_w.substr(first_quote + 1, second_quote - first_quote - 1);
    } else {
        size_t comma = path_w.find(L',');
        exe_path_w = (comma == std::wstring::npos) ? path_w : path_w.substr(0, comma);
    }

    size_t last_slash = exe_path_w.find_last_of(L"\\/");
    if (last_slash == std::wstring::npos) { return ""; }

    std::wstring dir_path_w = exe_path_w.substr(0, last_slash);

    const std::wstring candidates[] = {
        dir_path_w + L"\\Settings.json",
        dir_path_w + L"\\AppSettings.json"
    };

    for (const auto& candidate_w : candidates) {
        DWORD attrs = GetFileAttributesW(candidate_w.c_str());
        if (attrs != INVALID_FILE_ATTRIBUTES && !(attrs & FILE_ATTRIBUTE_DIRECTORY)) {
            int len = WideCharToMultiByte(CP_UTF8, 0, candidate_w.c_str(), -1, NULL, 0, NULL, NULL);
            if (len <= 0) continue;
            std::string settings_path(len, 0);
            WideCharToMultiByte(CP_UTF8, 0, candidate_w.c_str(), -1, &settings_path[0], len, NULL, NULL);
            if (!settings_path.empty() && settings_path.back() == '\0') settings_path.pop_back();
            return settings_path;
        }
    }

    return "";
}
std::string GetSelfExePath() {
    wchar_t path[MAX_PATH];
    DWORD pathLen = GetModuleFileNameW(NULL, path, MAX_PATH);
    if (pathLen == 0 || pathLen >= MAX_PATH) return "";
    std::wstring wpath = path;
    for (auto& c : wpath) {
        if (c == '\\') c = '/';
    }
    int len = WideCharToMultiByte(CP_UTF8, 0, wpath.c_str(), -1, NULL, 0, NULL, NULL);
    if (len <= 0) return "";
    std::string spath(len, 0);
    WideCharToMultiByte(CP_UTF8, 0, wpath.c_str(), -1, &spath[0], len, NULL, NULL);
    if (!spath.empty() && spath.back() == '\0') spath.pop_back();
    return spath;
}
void UpdateBloxstrapIntegration(bool enable) {
std::string settingsPath = GetBloxstrapSettingsPath();
if (settingsPath.empty()) {
ShowTrayNotification(L"AntiAFK-RBX • Integration Error", L"Could not find launcher installation path in registry.");
g_bloxstrapIntegration = false;
return;
}

std::wstring settingsPathW;
{
int wlen = MultiByteToWideChar(CP_UTF8, 0, settingsPath.c_str(), -1, NULL, 0);
if (wlen > 0) {
std::wstring wbuf(wlen, L'\0');
MultiByteToWideChar(CP_UTF8, 0, settingsPath.c_str(), -1, &wbuf[0], wlen);
if (!wbuf.empty() && wbuf.back() == L'\0') wbuf.pop_back();
settingsPathW = wbuf;
}
}

std::ifstream inFile(settingsPathW.c_str(), std::ios::binary);
    if (!inFile.is_open()) {
        ShowTrayNotification(L"AntiAFK-RBX • Integration Error", L"Could not find/open the launcher settings file.");
        g_bloxstrapIntegration = false;
        return;
    }

    std::stringstream buffer;
    buffer << inFile.rdbuf();
    std::string content = buffer.str();
    inFile.close();

    std::string integrationName = "AntiAFK-RBX \\u2022 AutoLaunch";
    size_t integrationPos = content.find(integrationName);

    if (enable) {
        if (integrationPos != std::string::npos) {
            return;
        }

        std::string selfPath = EscapeJsonStringUtf8(GetSelfExePath());
        if (selfPath.empty()) {
            ShowTrayNotification(L"AntiAFK-RBX • Integration Error", L"Could not determine the application path.");
            g_bloxstrapIntegration = false;
            return;
        }

        std::string integrationJson = "    {\r\n      \"Name\": \"" + integrationName + "\",\r\n      \"Location\": \"" + selfPath + "\",\r\n      \"LaunchArgs\": \"--bloxstrap-integration\",\r\n      \"Delay\": 0,\r\n      \"PreLaunch\": true,\r\n      \"AutoClose\": true\r\n    }";

        size_t integrationsArrayPos = content.find("\"CustomIntegrations\": [");
        if (integrationsArrayPos == std::string::npos) {
            ShowTrayNotification(L"AntiAFK-RBX • Integration Error", L"Could not find 'CustomIntegrations' array in the launcher settings file.");
            g_bloxstrapIntegration = false;
            return;
        }

        size_t openingBracket = content.find('[', integrationsArrayPos);
        size_t closingBracket = (openingBracket == std::string::npos) ? std::string::npos : FindUnquotedJsonChar(content, openingBracket + 1, ']');
        if (openingBracket == std::string::npos || closingBracket == std::string::npos) {
            ShowTrayNotification(L"AntiAFK-RBX • Integration Error", L"Could not find 'CustomIntegrations' array bounds in the launcher settings file.");
            g_bloxstrapIntegration = false;
            return;
        }
        bool isEmpty = true;
        for (size_t i = openingBracket + 1; i < closingBracket; ++i) {
            if (!isspace((unsigned char)content[i])) {
                isEmpty = false;
                break;
            }
        }

        if (!isEmpty) {
            content.insert(closingBracket, ",\r\n" + integrationJson);
        } else {
            content.insert(closingBracket, "\r\n" + integrationJson + "\r\n  ");
        }
    } else {
        if (integrationPos == std::string::npos) {
            return;
        }
        size_t start = content.rfind('{', integrationPos);
        size_t findEnd = (start == std::string::npos) ? std::string::npos : FindUnquotedJsonChar(content, start, '}');
        if (start == std::string::npos || findEnd == std::string::npos) {
            return;
        }
        size_t end = findEnd + 1;
        size_t comma_before = content.rfind(',', start);
        if (comma_before != std::string::npos && content.substr(comma_before + 1, start - (comma_before + 1)).find_first_not_of(" \r\n\t") == std::string::npos) {
            content.erase(comma_before, end - comma_before);
        } else {
            content.erase(start, end - start);
            size_t afterObject = start;
            while (afterObject < content.size() && isspace((unsigned char)content[afterObject])) ++afterObject;
            if (afterObject < content.size() && content[afterObject] == ',') {
                content.erase(afterObject, 1);
            }

            size_t integrationsArrayPos = content.find("\"CustomIntegrations\": [");
            size_t openingBracket = (integrationsArrayPos == std::string::npos) ? std::string::npos : content.find('[', integrationsArrayPos);
            size_t closingBracket = (openingBracket == std::string::npos) ? std::string::npos : content.find(']', openingBracket);
            if (openingBracket != std::string::npos && closingBracket != std::string::npos) {
                bool isEmpty = true;
                for (size_t i = openingBracket + 1; i < closingBracket; ++i) {
                    if (!isspace((unsigned char)content[i])) {
                        isEmpty = false; break;
                    }
                }
                if (isEmpty) content.erase(openingBracket + 1, closingBracket - (openingBracket + 1));
            }
        }
    }

    std::wstring tmpPathW = settingsPathW + L".tmp";
    {
        std::ofstream outFile(tmpPathW.c_str(), std::ios::binary);
        bool writeOk = false;
        if (outFile.is_open()) {
            outFile.write(content.data(), (std::streamsize)content.size());
            outFile.flush();
            writeOk = outFile.good() && (outFile.tellp() == (std::streampos)content.size());
            outFile.close();
        }
        if (!writeOk) {
            DeleteFileW(tmpPathW.c_str());
            ShowTrayNotification(L"AntiAFK-RBX • Integration Error", L"Failed to write to the launcher settings file. Check permissions.");
            g_bloxstrapIntegration = false;
            return;
        }
    }
    if (!MoveFileExW(tmpPathW.c_str(), settingsPathW.c_str(), MOVEFILE_REPLACE_EXISTING)) {
        DeleteFileW(tmpPathW.c_str());
        ShowTrayNotification(L"AntiAFK-RBX • Integration Error", L"Failed to write to the launcher settings file. Check permissions.");
        g_bloxstrapIntegration = false;
    }
}
