static HBITMAP CreateMenuIconFromAppIcon(int size = 0)
{
    if (size == 0) {
        HDC sdc = GetDC(NULL);
        size = MulDiv(16, GetDeviceCaps(sdc, LOGPIXELSY), 96);
        ReleaseDC(NULL, sdc);
    }
    HICON hIcon = (HICON)LoadImage(g_hInst, MAKEINTRESOURCE(IDI_MAIN), IMAGE_ICON, size, size, LR_DEFAULTCOLOR);
    if (!hIcon) return NULL;

    HDC hdc = GetDC(NULL);
    HDC memDC = CreateCompatibleDC(hdc);
    BITMAPINFO bmi = {};
    bmi.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bmi.bmiHeader.biWidth = size;
    bmi.bmiHeader.biHeight = -size;
    bmi.bmiHeader.biPlanes = 1;
    bmi.bmiHeader.biBitCount = 32;
    bmi.bmiHeader.biCompression = BI_RGB;
    void* bits = nullptr;
    HBITMAP hBmp = CreateDIBSection(hdc, &bmi, DIB_RGB_COLORS, &bits, NULL, 0);
    if (!hBmp || !bits) { DestroyIcon(hIcon); DeleteDC(memDC); ReleaseDC(NULL, hdc); return NULL; }
    SelectObject(memDC, hBmp);
    memset(bits, 0, size * size * 4);
    DrawIconEx(memDC, 0, 0, hIcon, size, size, 0, NULL, DI_NORMAL);
    DestroyIcon(hIcon);
    DeleteDC(memDC);
    ReleaseDC(NULL, hdc);
    return hBmp;
}

static HBITMAP CreateMenuIconFromTrayState(bool afk, int size = 0)
{
    HDC hdcDPI = GetDC(NULL);
    if (size == 0) {
        size = MulDiv(16, GetDeviceCaps(hdcDPI, LOGPIXELSY), 96);
    }
    ReleaseDC(NULL, hdcDPI);
    int iconId = IDI_TRAY_OFF;
    if (afk)
        iconId = g_multiSupport.load() ? IDI_TRAY_ON_MULTI : IDI_TRAY_ON;

    HICON hIcon = (HICON)LoadImage(g_hInst, MAKEINTRESOURCE(iconId), IMAGE_ICON, size, size, LR_DEFAULTCOLOR);
    if (!hIcon) return NULL;

    HDC hdc = GetDC(NULL);
    HDC memDC = CreateCompatibleDC(hdc);
    BITMAPINFO bmi = {};
    bmi.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bmi.bmiHeader.biWidth = size;
    bmi.bmiHeader.biHeight = -size;
    bmi.bmiHeader.biPlanes = 1;
    bmi.bmiHeader.biBitCount = 32;
    bmi.bmiHeader.biCompression = BI_RGB;
    void* bits = nullptr;
    HBITMAP hBmp = CreateDIBSection(hdc, &bmi, DIB_RGB_COLORS, &bits, NULL, 0);
    if (!hBmp || !bits) { DestroyIcon(hIcon); DeleteDC(memDC); ReleaseDC(NULL, hdc); return NULL; }
    SelectObject(memDC, hBmp);
    memset(bits, 0, size * size * 4);
    DrawIconEx(memDC, 0, 0, hIcon, size, size, 0, NULL, DI_NORMAL);
    DestroyIcon(hIcon);
    DeleteDC(memDC);
    ReleaseDC(NULL, hdc);
    return hBmp;
}

static void SetMenuIcon(HMENU hMenu, UINT itemId, wchar_t glyph, bool isChecked = false)
{
    if (!glyph) return;
    HBITMAP hBmp = CreateMenuIconFromGlyph(glyph, 0, RGB(200, 200, 200), isChecked);
    g_menuIconBitmaps.push_back(hBmp);
    MENUITEMINFO mii = { sizeof(mii) };
    mii.fMask = MIIM_BITMAP;
    mii.hbmpItem = hBmp;
    SetMenuItemInfo(hMenu, itemId, FALSE, &mii);
}

static void SetMenuIconPopup(HMENU hParent, HMENU hSub, wchar_t glyph)
{
    if (!glyph) return;
    HBITMAP hBmp = CreateMenuIconFromGlyph(glyph);
    g_menuIconBitmaps.push_back(hBmp);
    MENUITEMINFO mii = { sizeof(mii) };
    mii.fMask = MIIM_BITMAP;
    mii.hbmpItem = hBmp;
    SetMenuItemInfo(hParent, (UINT)(UINT_PTR)hSub, FALSE, &mii);
}

