std::wstring BuildDiscordPlainContentLine(DiscordWebhookEvent eventType, const std::wstring& summary)
{
    if (eventType == DiscordWebhookEvent::Started)
    {
        return std::wstring(L"AntiAFK-RBX ") + GetDiscordCompactVersionLabel() + L" • Started • " + BuildDiscordStartedCompactInstancesLabel();
    }

    std::wstring content = BuildDiscordPlainDescription(eventType, summary);
    for (wchar_t& ch : content)
    {
        if (ch == L'\n' || ch == L'\r')
        {
            ch = L' ';
        }
    }

    std::wstring compact;
    compact.reserve(content.size());
    bool previousWasSpace = false;
    for (wchar_t ch : content)
    {
        bool isSpace = iswspace(ch) != 0;
        if (isSpace)
        {
            if (!previousWasSpace)
            {
                compact.push_back(L' ');
            }
        }
        else
        {
            compact.push_back(ch);
        }
        previousWasSpace = isSpace;
    }

    while (!compact.empty() && compact.front() == L' ')
    {
        compact.erase(compact.begin());
    }
    while (!compact.empty() && compact.back() == L' ')
    {
        compact.pop_back();
    }

    compact = std::wstring(L"AntiAFK-RBX ") + GetDiscordCompactVersionLabel() + L" • " + compact;
    return compact;
}

std::string BuildDiscordWebhookPayloadJson(DiscordWebhookEvent eventType, const std::wstring& summary)
{
    std::wstring mentionText = ShouldMentionDiscordEvent(eventType) ? GetDiscordMentionTargetCopy() : L"";
    std::string mentionUtf8 = EscapeJsonStringUtf8(WideToUtf8(mentionText));
    const char* allowedMentionsJson = mentionText.empty()
        ? "{\"parse\":[]}"
        : "{\"parse\":[\"everyone\",\"users\",\"roles\"]}";

    std::wstring botNameUtf8W = L"AntiAFK-RBX";
    std::string botNameUtf8 = EscapeJsonStringUtf8(WideToUtf8(botNameUtf8W));
    std::string headFields;
    if (!g_discordUseDefaultName.load()) {
        headFields = "\"username\":\"" + botNameUtf8 + "\"";
    }
    if (!g_discordUseDefaultAvatar.load()) {
        std::wstring avatarUrl = GetDiscordAuthorIconUrl();
        if (!avatarUrl.empty()) {
            if (!headFields.empty()) headFields += ",";
            headFields += "\"avatar_url\":\"" + EscapeJsonStringUtf8(WideToUtf8(avatarUrl)) + "\"";
        }
    }
    std::string headComma = headFields.empty() ? "" : ",";

    if (g_discordDisableEmbed.load())
    {
        std::wstring content = BuildDiscordPlainContentLine(eventType, summary);
        if (!mentionText.empty())
        {
            content = mentionText + L" " + content;
        }
        std::string contentUtf8 = EscapeJsonStringUtf8(WideToUtf8(content));

        std::ostringstream json;
        json
            << "{" << headFields << headComma << "\"allowed_mentions\":" << allowedMentionsJson << ",\"content\":\""
            << contentUtf8
            << "\"}";
        return json.str();
    }

    std::wstring title = BuildDiscordEmbedTitle(eventType);
    std::wstring description = BuildDiscordEmbedDescription(eventType, summary);
    std::wstring authorName = L"AntiAFK-RBX " + GetDiscordCompactVersionLabel();
    std::wstring authorUrl = GetGithubRepoUrl();
    std::wstring authorIconUrl = GetDiscordAuthorIconUrl();

    std::string titleUtf8 = EscapeJsonStringUtf8(WideToUtf8(title));
    std::string descriptionUtf8 = EscapeJsonStringUtf8(WideToUtf8(description));
    std::string authorNameUtf8 = EscapeJsonStringUtf8(WideToUtf8(authorName));
    std::string authorUrlUtf8 = EscapeJsonStringUtf8(WideToUtf8(authorUrl));
    std::string authorIconUrlUtf8 = EscapeJsonStringUtf8(WideToUtf8(authorIconUrl));

    std::ostringstream json;
    json
        << "{" << headFields << headComma << "\"allowed_mentions\":" << allowedMentionsJson << ",\"content\":";
    if (!mentionText.empty())
    {
        json << "\"" << mentionUtf8 << "\"";
    }
    else
    {
        json << "null";
    }
    json
        << ",\"embeds\":[{"
        << "\"title\":\"" << titleUtf8 << "\","
        << "\"description\":\"" << descriptionUtf8 << "\","
        << "\"author\":{\"name\":\"" << authorNameUtf8 << "\",\"url\":\"" << authorUrlUtf8 << "\",\"icon_url\":\"" << authorIconUrlUtf8 << "\"},"
        << "\"color\":" << GetDiscordEventColor(eventType);
    if (g_discordUseTimestamp.load()) {
        json << ",\"timestamp\":\"" << EscapeJsonStringUtf8(WideToUtf8(GetDiscordUtcTimestamp())) << "\"";
    }
    json
        << "}],\"attachments\":[]}";
    return json.str();
}

uint64_t FinalizeAfkSession()
{
    uint64_t startTime = g_afkStartTime.exchange(0);
    if (startTime == 0)
    {
        return 0;
    }

    uint64_t sessionSeconds = (GetTickCount64() - startTime) / 1000;
    g_totalAfkTimeSeconds += sessionSeconds;
    g_afkSessionsCompleted++;
    g_lastSessionDurationSeconds = sessionSeconds;
    g_lastHeartbeatSend = 0;

    uint64_t longestSession = g_longestAfkSessionSeconds.load();
    while (sessionSeconds > longestSession && !g_longestAfkSessionSeconds.compare_exchange_weak(longestSession, sessionSeconds))
    {
    }

    return sessionSeconds;
}

std::wstring FormatDurationShort(uint64_t totalSeconds)
{
    uint64_t hours = totalSeconds / 3600;
    uint64_t minutes = (totalSeconds % 3600) / 60;

    wchar_t buffer[64];
    if (totalSeconds < 60) {
        swprintf_s(buffer, L"%llu sec", (unsigned long long)totalSeconds);
    } else if (hours == 0) {
        swprintf_s(buffer, L"%llu min", (unsigned long long)minutes);
    } else {
        swprintf_s(buffer, L"%llu h %llu min", (unsigned long long)hours, (unsigned long long)minutes);
    }
    return buffer;
}

std::wstring BuildDiscordSessionStatsLine(uint64_t lastSessionSeconds)
{
    wchar_t buffer[224];
    swprintf_s(buffer, L"Session: %s • Actions: %llu • Reconnects: %llu • Sessions completed: %llu",
        FormatDurationShort(lastSessionSeconds).c_str(),
        (unsigned long long)g_sessionAfkActions.load(),
        (unsigned long long)g_sessionReconnects.load(),
        (unsigned long long)g_afkSessionsCompleted.load());
    return buffer;
}

std::wstring BuildDiscordTotalStatsLine()
{
    wchar_t buffer[224];
    swprintf_s(buffer, L"Total time: %s • Actions: %llu • Macros: %llu • Reconnects: %llu • Sessions completed: %llu",
        FormatDurationShort(g_totalAfkTimeSeconds.load()).c_str(),
        (unsigned long long)g_afkActionsPerformed.load(),
        (unsigned long long)g_macroRunsPerformed.load(),
        (unsigned long long)g_autoReconnectsPerformed.load(),
        (unsigned long long)g_afkSessionsCompleted.load());
    return buffer;
}

bool ShouldSendDiscordWebhookEvent(DiscordWebhookEvent eventType, bool bypassEnabledCheck = false)
{
    if (eventType == DiscordWebhookEvent::Test)
    {
        return true;
    }

    if (!bypassEnabledCheck && (g_simpleMode.load() || !g_discordWebhookEnabled.load()))
    {
        return false;
    }

    switch (eventType)
    {
    case DiscordWebhookEvent::Started: return g_discordNotifyStart.load();
    case DiscordWebhookEvent::Stopped: return g_discordNotifyStop.load();
    case DiscordWebhookEvent::Action: return g_discordNotifyAction.load();
    case DiscordWebhookEvent::AutoReconnect: return g_discordNotifyReconnect.load();
    case DiscordWebhookEvent::AutoReset: return g_discordNotifyReset.load();
    case DiscordWebhookEvent::Error: return g_discordNotifyErrors.load();
    case DiscordWebhookEvent::Macro: return g_discordNotifyMacro.load();
    case DiscordWebhookEvent::IntervalMacrosStarted:
    case DiscordWebhookEvent::IntervalMacrosStopped: return g_discordNotifyIntervalMacros.load();
    case DiscordWebhookEvent::Heartbeat: return g_discordNotifyHeartbeat.load();
    case DiscordWebhookEvent::UtilityRam: return g_discordNotifyUtilsRam.load();
    case DiscordWebhookEvent::Test: return true;
    }
    return false;
}

bool ReadUnicodeTextFromClipboard(HWND owner, std::wstring& outText)
{
    outText.clear();
    if (!OpenClipboard(owner))
    {
        return false;
    }

    HANDLE clipboardData = GetClipboardData(CF_UNICODETEXT);
    if (!clipboardData)
    {
        CloseClipboard();
        return false;
    }

    const wchar_t* rawText = (const wchar_t*)GlobalLock(clipboardData);
    if (!rawText)
    {
        CloseClipboard();
        return false;
    }

    outText = rawText;
    GlobalUnlock(clipboardData);
    CloseClipboard();
    return true;
}

bool TryParseOnOffValue(const std::wstring& value, bool& outValue)
{
    if (value == L"on")
    {
        outValue = true;
        return true;
    }
    if (value == L"off")
    {
        outValue = false;
        return true;
    }
    return false;
}

bool ReadOptionalOnOffArgument(LPWSTR* argv, int argc, int& index, bool defaultValue, bool& outValue)
{
    outValue = defaultValue;
    if (index + 1 >= argc)
    {
        return false;
    }

    bool parsedValue = false;
    if (!TryParseOnOffValue(argv[index + 1], parsedValue))
    {
        return false;
    }

    outValue = parsedValue;
    ++index;
    return true;
}

void ResetStatisticsCounters()
{
    g_totalAfkTimeSeconds = 0;
    g_afkActionsPerformed = 0;
    g_macroRunsPerformed = 0;
    g_autoReconnectsPerformed = 0;
    g_longestAfkSessionSeconds = 0;
    g_discordWebhooksSent = 0;
    g_programLaunches = 0;
    g_afkSessionsCompleted = 0;
    SaveSettings();
}

bool SendDiscordWebhookRequest(const std::wstring& webhookUrl, DiscordWebhookEvent eventType, const std::wstring& summary, std::wstring* errorOut = nullptr, DWORD* statusCodeOut = nullptr, DWORD* retryAfterMsOut = nullptr)
{
    std::wstring normalizedUrl = NormalizeDiscordWebhookUrl(webhookUrl);
    if (!IsDiscordWebhookUrl(normalizedUrl))
    {
        if (errorOut) *errorOut = L"Webhook URL is empty or invalid.";
        return false;
    }

    URL_COMPONENTS components = { 0 };
    wchar_t host[256] = { 0 };
    wchar_t path[2048] = { 0 };
    wchar_t extraInfo[2048] = { 0 };
    components.dwStructSize = sizeof(components);
    components.lpszHostName = host;
    components.dwHostNameLength = _countof(host);
    components.lpszUrlPath = path;
    components.dwUrlPathLength = _countof(path);
    components.lpszExtraInfo = extraInfo;
    components.dwExtraInfoLength = _countof(extraInfo);

    if (!InternetCrackUrlW(normalizedUrl.c_str(), 0, 0, &components))
    {
        if (errorOut) *errorOut = GetWin32ErrorText(GetLastError());
        return false;
    }

    std::wstring requestPath(path, components.dwUrlPathLength);
    requestPath.append(extraInfo, components.dwExtraInfoLength);

    HINTERNET hInternet = InternetOpenW(L"AntiAFK-RBX/4.0", INTERNET_OPEN_TYPE_PRECONFIG, NULL, NULL, 0);
    if (!hInternet)
    {
        if (errorOut) *errorOut = GetWin32ErrorText(GetLastError());
        return false;
    }

    DWORD webhookTimeoutMs = 15000;
    InternetSetOption(hInternet, INTERNET_OPTION_CONNECT_TIMEOUT, &webhookTimeoutMs, sizeof(webhookTimeoutMs));
    InternetSetOption(hInternet, INTERNET_OPTION_SEND_TIMEOUT, &webhookTimeoutMs, sizeof(webhookTimeoutMs));
    InternetSetOption(hInternet, INTERNET_OPTION_RECEIVE_TIMEOUT, &webhookTimeoutMs, sizeof(webhookTimeoutMs));

    bool success = false;
    HINTERNET hConnect = NULL;
    HINTERNET hRequest = NULL;

    do
    {
        hConnect = InternetConnectW(
            hInternet,
            host,
            components.nPort,
            NULL,
            NULL,
            INTERNET_SERVICE_HTTP,
            0,
            0);
        if (!hConnect)
        {
            if (errorOut) *errorOut = GetWin32ErrorText(GetLastError());
            break;
        }

        const wchar_t* acceptTypes[] = { L"*/*", NULL };
        hRequest = HttpOpenRequestW(
            hConnect,
            L"POST",
            requestPath.c_str(),
            NULL,
            NULL,
            acceptTypes,
            INTERNET_FLAG_SECURE | INTERNET_FLAG_RELOAD | INTERNET_FLAG_NO_CACHE_WRITE | INTERNET_FLAG_NO_UI,
            0);
        if (!hRequest)
        {
            if (errorOut) *errorOut = GetWin32ErrorText(GetLastError());
            break;
        }

        std::string jsonBody = BuildDiscordWebhookPayloadJson(eventType, summary);

        const wchar_t* headers = L"Content-Type: application/json\r\n";
        if (!HttpSendRequestW(hRequest, headers, static_cast<DWORD>(-1), (LPVOID)jsonBody.data(), (DWORD)jsonBody.size()))
        {
            if (errorOut) *errorOut = GetWin32ErrorText(GetLastError());
            break;
        }

        DWORD statusCode = 0;
        DWORD statusSize = sizeof(statusCode);
        if (!HttpQueryInfoW(hRequest, HTTP_QUERY_STATUS_CODE | HTTP_QUERY_FLAG_NUMBER, &statusCode, &statusSize, NULL))
        {
            if (errorOut) *errorOut = GetWin32ErrorText(GetLastError());
            break;
        }

        if (statusCodeOut) *statusCodeOut = statusCode;
        if (retryAfterMsOut && statusCode == 429) {
            wchar_t retryBuf[32] = { 0 };
            DWORD retryLen = sizeof(retryBuf);
            if (HttpQueryInfoW(hRequest, HTTP_QUERY_RETRY_AFTER, retryBuf, &retryLen, NULL)) {
                double sec = _wtof(retryBuf);
                if (sec > 0.0) {
                    DWORD ms = (DWORD)(sec * 1000.0);
                    if (ms < 500) ms = 500;
                    if (ms > 15000) ms = 15000;
                    *retryAfterMsOut = ms;
                }
            }
        }

        if (statusCode >= 200 && statusCode < 300)
        {
            success = true;
            g_discordWebhooksSent++;
            break;
        }

        std::string responseBody;
        char buffer[512];
        DWORD bytesRead = 0;
        while (responseBody.size() < 512 && InternetReadFile(hRequest, buffer, sizeof(buffer), &bytesRead) && bytesRead > 0)
        {
            responseBody.append(buffer, bytesRead);
            bytesRead = 0;
        }

        if (errorOut)
        {
            std::wstringstream errorStream;
            errorStream << L"Discord returned HTTP " << statusCode;
            if (!responseBody.empty())
            {
                std::wstring bodyText = Utf8ToWide(responseBody);
                if (!bodyText.empty())
                {
                    errorStream << L": " << bodyText;
                }
            }
            *errorOut = errorStream.str();
        }
    } while (false);

    if (hRequest) InternetCloseHandle(hRequest);
    if (hConnect) InternetCloseHandle(hConnect);
    InternetCloseHandle(hInternet);
    return success;
}

static void QueueWebhookTestAsync(const std::wstring& webhookUrl, const std::wstring& sourceNote)
{
    std::thread([webhookUrl, sourceNote]() {
        std::wstring errorText;
        DWORD statusCode = 0;
        bool sent = SendDiscordWebhookRequest(
            webhookUrl,
            DiscordWebhookEvent::Test,
            L"Manual test message from " + sourceNote + L".",
            &errorText,
            &statusCode);
        std::wstring body;
        if (sent) {
            body = L"Test message sent successfully (HTTP " + std::to_wstring(statusCode) + L").";
        } else {
            body = errorText.empty() ? std::wstring(L"Failed to send the test webhook.") : errorText;
        }
        {
            std::lock_guard<std::mutex> errorLock(g_lastWebhookErrorMutex);
            g_lastWebhookError = sent ? std::wstring() : (statusCode > 0 ? (L"HTTP " + std::to_wstring(statusCode)) : body);
        }
        std::wstring* payload = new std::wstring(body);
        HWND target = (g_hMainUiWnd && IsWindow(g_hMainUiWnd)) ? g_hMainUiWnd : g_hwnd;
        if (!target || !IsWindow(target) || !PostMessage(target, WM_APP_WEBHOOK_TEST_RESULT, reinterpret_cast<WPARAM>(payload), 0)) {
            delete payload;
        }
    }).detach();
}

void WebhookWorkerThread()
{
    std::wstring webhookUrl = GetDiscordWebhookUrlCopy();
    while (g_webhookThreadRunning) {
        std::pair<DiscordWebhookEvent, std::wstring> item;
        {
            std::unique_lock<std::mutex> lock(g_discordWebhookMutex);
            g_webhookCv.wait_for(lock, std::chrono::seconds(3), [] { return !g_webhookQueue.empty() || !g_webhookThreadRunning; });
            if (!g_webhookThreadRunning) break;
            if (g_webhookQueue.empty()) continue;
            item = std::move(g_webhookQueue.front());
            g_webhookQueue.pop();
            g_webhookBusy = true;
        }
        webhookUrl = GetDiscordWebhookUrlCopy();
        if (IsDiscordWebhookUrl(webhookUrl)) {
            try {
                std::wstring error;
                DWORD statusCode = 0;
                DWORD retryAfterMs = 1000;
                bool sent = SendDiscordWebhookRequest(webhookUrl, item.first, item.second, &error, &statusCode, &retryAfterMs);
                for (int attempt = 0; !sent && (statusCode == 429 || statusCode >= 500) && attempt < 2 && g_webhookThreadRunning && !g_stopThread.load(); ++attempt) {
                    DWORD waitMs = (statusCode == 429 && retryAfterMs > 0) ? retryAfterMs : 1000;
                    for (DWORD waited = 0; waited < waitMs && g_webhookThreadRunning && !g_stopThread.load(); waited += 100) {
                        Sleep((std::min)((DWORD)100, waitMs - waited));
                    }
                    if (g_webhookThreadRunning && !g_stopThread.load()) {
                        error.clear();
                        statusCode = 0;
                        retryAfterMs = 1000;
                        sent = SendDiscordWebhookRequest(webhookUrl, item.first, item.second, &error, &statusCode, &retryAfterMs);
                    }
                }
                {
                    std::lock_guard<std::mutex> errorLock(g_lastWebhookErrorMutex);
                    if (sent) {
                        g_lastWebhookError.clear();
                    } else {
                        g_lastWebhookError = statusCode > 0 ? (L"HTTP " + std::to_wstring(statusCode)) : (error.empty() ? L"Send failed" : error);
                    }
                }
                if (g_webhookThreadRunning && !g_stopThread.load()) {
                    Sleep(200);
                }
            } catch (...) {
                std::lock_guard<std::mutex> errorLock(g_lastWebhookErrorMutex);
                g_lastWebhookError = L"Exception while sending";
            }
        }
        g_webhookBusy = false;
        g_webhookCv.notify_all();
    }
}

void QueueDiscordWebhookEvent(DiscordWebhookEvent eventType, const std::wstring& summary, bool bypassEnabledCheck)
{
    if (!ShouldSendDiscordWebhookEvent(eventType, bypassEnabledCheck))
    {
        return;
    }

    std::wstring webhookUrl = GetDiscordWebhookUrlCopy();
    if (!IsDiscordWebhookUrl(webhookUrl))
    {
        return;
    }

    {
        std::lock_guard<std::mutex> lock(g_discordWebhookMutex);
        if (g_webhookQueue.size() >= 256) {
            g_webhookQueue.pop();
        }
        g_webhookQueue.emplace(eventType, summary);
    }
    g_webhookCv.notify_one();
}
