static bool SaveTextFileUtf8(const std::wstring& path, const std::wstring& content)
{
    std::ofstream outFile(path, std::ios::binary);
    if (!outFile.is_open()) return false;
    int bytesNeeded = WideCharToMultiByte(CP_UTF8, 0, content.c_str(), -1, NULL, 0, NULL, NULL);
    if (bytesNeeded <= 0) return false;
    std::string utf8(bytesNeeded, '\0');
    WideCharToMultiByte(CP_UTF8, 0, content.c_str(), -1, &utf8[0], bytesNeeded, NULL, NULL);
    outFile.write(utf8.data(), (std::streamsize)(bytesNeeded - 1));
    return outFile.good();
}

static bool LoadTextFileUtf8(const std::wstring& path, std::wstring& content)
{
    std::ifstream inFile(path, std::ios::binary);
    if (!inFile.is_open()) return false;
    inFile.seekg(0, std::ios::end);
    std::streamoff fileSize = inFile.tellg();
    if (fileSize <= 0 || fileSize > 5 * 1024 * 1024) return false;
    inFile.seekg(0, std::ios::beg);
    std::string bytes((std::istreambuf_iterator<char>(inFile)), std::istreambuf_iterator<char>());
    if (bytes.empty()) return false;
    int charsNeeded = MultiByteToWideChar(CP_UTF8, 0, bytes.c_str(), (int)bytes.size(), NULL, 0);
    if (charsNeeded <= 0) return false;
    content.resize(charsNeeded);
    MultiByteToWideChar(CP_UTF8, 0, bytes.c_str(), (int)bytes.size(), &content[0], charsNeeded);
    return true;
}

static bool FindJsonValue(const std::wstring& json, const std::wstring& key, std::wstring& rawValue)
{
    std::wstring searchKey = L"\"" + key + L"\"";
    size_t i = 0;
    bool inString = false;
    bool escape = false;

    while (i < json.size()) {
        wchar_t c = json[i];
        if (inString) {
            if (escape) {
                escape = false;
            } else if (c == L'\\') {
                escape = true;
            } else if (c == L'"') {
                inString = false;
            }
            ++i;
            continue;
        }
        if (c == L'"') {
            if (json.compare(i, searchKey.size(), searchKey) == 0) {
                size_t afterKey = i + searchKey.size();
                while (afterKey < json.size() && iswspace(json[afterKey])) ++afterKey;
                if (afterKey < json.size() && json[afterKey] == L':') {
                    size_t valPos = afterKey + 1;
                    while (valPos < json.size() && iswspace(json[valPos])) ++valPos;
                size_t end = valPos;
                if (valPos < json.size() && json[valPos] == L'"') {
                    ++valPos;
                    end = valPos;
                    bool valEscape = false;
                    while (end < json.size()) {
                        if (!valEscape && json[end] == L'"') break;
                        valEscape = (!valEscape && json[end] == L'\\');
                        ++end;
                    }
                    if (end >= json.size()) return false;
                    rawValue = json.substr(valPos, end - valPos);
                    return true;
                }
                while (end < json.size() && json[end] != L',' && json[end] != L'}' && json[end] != L'\r' && json[end] != L'\n') ++end;
                rawValue = json.substr(valPos, end - valPos);
                rawValue.erase(0, rawValue.find_first_not_of(L" \t"));
                rawValue.erase(rawValue.find_last_not_of(L" \t") + 1);
                return !rawValue.empty();
                }
            }
            inString = true;
            escape = false;
        }
        ++i;
    }
    return false;
}

static bool ParseJsonBool(const std::wstring& json, const std::wstring& key, bool& value)
{
    std::wstring raw;
    if (!FindJsonValue(json, key, raw)) return false;
    for (auto& ch : raw) ch = (wchar_t)towlower(ch);
    if (raw == L"true" || raw == L"1") { value = true; return true; }
    if (raw == L"false" || raw == L"0") { value = false; return true; }
    return false;
}

static bool IsJsonIntegerToken(const std::wstring& raw)
{
    size_t i = 0;
    while (i < raw.size() && iswspace(raw[i])) ++i;
    size_t end = raw.size();
    while (end > i && iswspace(raw[end - 1])) --end;
    if (i >= end) return false;
    if (raw[i] == L'-' || raw[i] == L'+') ++i;
    if (i >= end) return false;
    for (; i < end; ++i) {
        if (raw[i] < L'0' || raw[i] > L'9') return false;
    }
    return true;
}

static bool ParseJsonInt(const std::wstring& json, const std::wstring& key, int& value)
{
    std::wstring raw;
    if (!FindJsonValue(json, key, raw)) return false;
    if (!IsJsonIntegerToken(raw)) return false;
    try { value = std::stoi(raw); return true; } catch (...) { return false; }
}

static bool ParseJsonUInt64(const std::wstring& json, const std::wstring& key, uint64_t& value)
{
    std::wstring raw;
    if (!FindJsonValue(json, key, raw)) return false;
    if (!IsJsonIntegerToken(raw) || raw[0] == L'-') return false;
    try { value = std::stoull(raw); return true; } catch (...) { return false; }
}

static bool ParseJsonString(const std::wstring& json, const std::wstring& key, std::wstring& value)
{
    std::wstring raw;
    if (!FindJsonValue(json, key, raw)) return false;
    if (raw.empty()) {
        value.clear();
        return true;
    }
    std::wstring out;
    out.reserve(raw.size());
    for (size_t i = 0; i < raw.size(); ++i) {
        if (raw[i] == L'\\' && i + 1 < raw.size()) {
            wchar_t next = raw[++i];
            switch (next) {
            case L'\\': out.push_back(L'\\'); break;
            case L'"': out.push_back(L'"'); break;
            case L'n': out.push_back(L'\n'); break;
            case L'r': out.push_back(L'\r'); break;
            case L't': out.push_back(L'\t'); break;
            case L'b': out.push_back(L'\b'); break;
            case L'f': out.push_back(L'\f'); break;
            case L'u':
                if (i + 4 < raw.size()) {
                    wchar_t* endPtr = nullptr;
                    std::wstring hex = raw.substr(i + 1, 4);
                    long codePoint = wcstol(hex.c_str(), &endPtr, 16);
                    if (endPtr && *endPtr == L'\0' && codePoint > 0 && codePoint <= 0xFFFF) {
                        out.push_back((wchar_t)codePoint);
                        i += 4;
                        break;
                    }
                }
                out.push_back(L'u');
                break;
            default: out.push_back(next); break;
            }
        } else {
            out.push_back(raw[i]);
        }
    }
    value = out;
    return true;
}

static int RunJsonSelfTests()
{
    int failures = 0;
    std::wstring report;
    auto check = [&](bool cond, const wchar_t* name) {
        if (!cond) {
            ++failures;
            report += L"FAIL: ";
        } else {
            report += L"PASS: ";
        }
        report += name;
        report += L"\r\n";
    };

    const std::wstring json = L"{\"Alpha\":true,\"Number\":42,\"Text\":\"hello \\\"world\\\"\",\"Escaped\":\"line\\nbreak\",\"Unicode\":\"\\u0041\",\"Fake\":\"\\\"Alpha\\\":false\"}";
    bool b = false;
    check(ParseJsonBool(json, L"Alpha", b) && b, L"bool true");
    check(ParseJsonBool(json, L"Missing", b) == false, L"missing bool rejected");
    int i = 0;
    check(ParseJsonInt(json, L"Number", i) && i == 42, L"int value");
    check(ParseJsonInt(json, L"Text", i) == false, L"non-int rejected");
    std::wstring s;
    check(ParseJsonString(json, L"Text", s) && s == L"hello \"world\"", L"escaped string");
    check(ParseJsonString(json, L"Escaped", s) && s == L"line\nbreak", L"newline escape");
    check(ParseJsonString(json, L"Unicode", s) && s == L"A", L"unicode escape");
    check(ParseJsonString(json, L"Fake", s) && s == L"\"Alpha\":false", L"key inside string ignored");
    check(ParseJsonInt(L"{\"Number\":}", L"Number", i) == false, L"malformed value rejected");
    check(ParseJsonInt(L"{\"Number\" 42}", L"Number", i) == false, L"missing colon rejected");

    std::wstring outPath = GetFpsSuspendMarkerPath();
    size_t slash = outPath.find_last_of(L"\\/");
    if (slash != std::wstring::npos) outPath = outPath.substr(0, slash + 1);
    outPath += L"AntiAFK-RBX-selftest.txt";
    wchar_t summary[64];
    swprintf_s(summary, L"JSON self-test: %d failure(s)\r\n\r\n", failures);
    report = std::wstring(summary) + report;
    SaveTextFileUtf8(outPath, report);
    return failures == 0 ? 0 : 1;
}

static std::wstring TrimAnnouncementField(std::wstring value, size_t maxLength)
{
    value.erase(0, value.find_first_not_of(L" \t\r\n"));
    size_t last = value.find_last_not_of(L" \t\r\n");
    if (last == std::wstring::npos)
    {
        value.clear();
    }
    else
    {
        value.erase(last + 1);
    }

    for (wchar_t& ch : value)
    {
        if (ch == L'\r' || ch == L'\n' || ch == L'\t')
        {
            ch = L' ';
        }
    }

    if (value.size() > maxLength)
    {
        value.resize(maxLength);
    }
    return value;
}

static bool ParseAnnouncementIconColor(const std::wstring& rawColor, COLORREF& outColor)
{
    std::wstring value = TrimAnnouncementField(rawColor, 16);
    if (value.empty())
    {
        return false;
    }

    if (value[0] == L'#')
    {
        value.erase(value.begin());
    }
    else if (value.size() > 2 && value[0] == L'0' && (value[1] == L'x' || value[1] == L'X'))
    {
        value.erase(0, 2);
    }

    if (value.size() != 6)
    {
        return false;
    }

    wchar_t* endPtr = nullptr;
    long rgb = wcstol(value.c_str(), &endPtr, 16);
    if (!endPtr || *endPtr != L'\0' || rgb < 0 || rgb > 0xFFFFFF)
    {
        return false;
    }

    outColor = RGB((rgb >> 16) & 0xFF, (rgb >> 8) & 0xFF, rgb & 0xFF);
    return true;
}

static bool DownloadTextUrl(const wchar_t* url, std::string& outText, DWORD timeoutMs = 5000, size_t maxBytes = 8192)
{
    outText.clear();
    HINTERNET hInternet = InternetOpen(L"AntiAFK-RBX/4.0", INTERNET_OPEN_TYPE_PRECONFIG, NULL, NULL, 0);
    if (!hInternet)
    {
        return false;
    }

    InternetSetOption(hInternet, INTERNET_OPTION_CONNECT_TIMEOUT, &timeoutMs, sizeof(timeoutMs));
    InternetSetOption(hInternet, INTERNET_OPTION_SEND_TIMEOUT, &timeoutMs, sizeof(timeoutMs));
    InternetSetOption(hInternet, INTERNET_OPTION_RECEIVE_TIMEOUT, &timeoutMs, sizeof(timeoutMs));

    HINTERNET hConnect = InternetOpenUrl(hInternet, url, NULL, 0, INTERNET_FLAG_RELOAD | INTERNET_FLAG_SECURE | INTERNET_FLAG_NO_CACHE_WRITE | INTERNET_FLAG_NO_UI, 0);
    if (!hConnect)
    {
        InternetCloseHandle(hInternet);
        return false;
    }

    DWORD statusCode = 0;
    DWORD statusSize = sizeof(statusCode);
    if (HttpQueryInfoW(hConnect, HTTP_QUERY_STATUS_CODE | HTTP_QUERY_FLAG_NUMBER, &statusCode, &statusSize, NULL)) {
        if (statusCode < 200 || statusCode >= 300) {
            InternetCloseHandle(hConnect);
            InternetCloseHandle(hInternet);
            return false;
        }
    }

    char buffer[512] = { 0 };
    DWORD bytesRead = 0;
    bool ok = true;
    BOOL readOk = FALSE;
    while ((readOk = InternetReadFile(hConnect, buffer, sizeof(buffer), &bytesRead)) && bytesRead > 0)
    {
        if (outText.size() + bytesRead > maxBytes)
        {
            ok = false;
            break;
        }
        outText.append(buffer, bytesRead);
        bytesRead = 0;
    }
    if (!readOk) ok = false;

    InternetCloseHandle(hConnect);
    InternetCloseHandle(hInternet);
    return ok && !outText.empty();
}

AnnouncementInfo GetAnnouncementCopy()
{
    std::lock_guard<std::mutex> lock(g_announcementMutex);
    return g_announcement;
}

bool CheckForAnnouncement(bool showNotification)
{
    static const wchar_t* ANNOUNCEMENT_URL = GetAnnouncementUrl();

    std::string bytes;
    AnnouncementInfo nextAnnouncement;

    if (DownloadTextUrl(ANNOUNCEMENT_URL, bytes, 4000, 8192))
    {
        std::wstring json = Utf8ToWide(bytes);
        bool enabled = false;
        ParseJsonBool(json, L"enabled", enabled);
        ParseJsonBool(json, L"isEnabled", enabled);

        if (enabled)
        {
            bool notify = false;
            std::wstring icon, iconColor, title, description;
            COLORREF parsedIconColor = RGB(0, 180, 216);

            ParseJsonBool(json, L"notify", notify);
            ParseJsonBool(json, L"isNotify", notify);
            ParseJsonString(json, L"icon", icon);
            ParseJsonString(json, L"iconColor", iconColor);
            ParseJsonString(json, L"color", iconColor);
            ParseJsonString(json, L"title", title);
            ParseJsonString(json, L"text", title);
            ParseJsonString(json, L"description", description);
            ParseJsonString(json, L"desc", description);
            ParseAnnouncementIconColor(iconColor, parsedIconColor);

            nextAnnouncement.notify = notify;
            nextAnnouncement.icon = TrimAnnouncementField(icon.empty() ? L"\uE7F4" : icon, 2);
            nextAnnouncement.iconColor = parsedIconColor;
            nextAnnouncement.title = TrimAnnouncementField(title, 80);
            nextAnnouncement.description = TrimAnnouncementField(description, 140);
            nextAnnouncement.enabled = !nextAnnouncement.title.empty();
        }

        {
            std::lock_guard<std::mutex> lock(g_announcementMutex);
            g_announcement = nextAnnouncement;
        }
    }

    if (nextAnnouncement.enabled && showNotification && nextAnnouncement.notify)
    {
        const std::wstring notificationText = nextAnnouncement.description.empty() ? nextAnnouncement.title : nextAnnouncement.description;
        ShowTrayNotification(nextAnnouncement.title.c_str(), notificationText.c_str());
    }

    if (g_hMainUiWnd && IsWindow(g_hMainUiWnd))
    {
        InvalidateRect(g_hMainUiWnd, NULL, FALSE);
    }
    if (g_hwnd)
    {
        QueueRefreshTrayMenu(g_isAfkStarted.load());
    }

    return nextAnnouncement.enabled;
}

