void UpdateTrayIcon()
{
    std::lock_guard<std::mutex> lock(g_trayIconMutex);
    if (g_isAfkStarted.load()) {
        uint64_t last = g_lastAfkActionTimestamp.load();
        if (last == 0) last = g_afkStartTime.load();
        uint64_t interval = (uint64_t)g_selectedTime.load();
        uint64_t elapsed = last > 0 ? (GetTickCount64() - last) / 1000 : 0;
        uint64_t remain = elapsed < interval ? interval - elapsed : 0;
        StringCchPrintfW(g_nid.szTip, ARRAYSIZE(g_nid.szTip), L"AntiAFK-RBX • Running • next %02llu:%02llu", remain / 60, remain % 60);
    } else {
        StringCchPrintfW(g_nid.szTip, ARRAYSIZE(g_nid.szTip), L"AntiAFK-RBX • Stopped");
    }
    HICON oldIcon = g_nid.hIcon;
    g_nid.hIcon = CreateCustomIcon();
    bool ok = Shell_NotifyIcon(NIM_MODIFY, &g_nid) != FALSE;
    if (ok) {
        if (oldIcon && oldIcon != g_nid.hIcon) DestroyIcon(oldIcon);
    } else {
        if (g_nid.hIcon && g_nid.hIcon != oldIcon) DestroyIcon(g_nid.hIcon);
        g_nid.hIcon = oldIcon;
    }
}

static constexpr UINT TRAY_READD_RETRY_TIMER = 9001;
static constexpr UINT TRAY_TIP_TIMER = 9002;
static constexpr int TRAY_READD_MAX_ATTEMPTS = 10;
static int g_trayReaddAttempts = 0;

static bool TryReAddTrayIcon(HWND hwnd)
{
    std::lock_guard<std::mutex> lock(g_trayIconMutex);
    if (g_isAfkStarted.load()) {
        uint64_t last = g_lastAfkActionTimestamp.load();
        if (last == 0) last = g_afkStartTime.load();
        uint64_t interval = (uint64_t)g_selectedTime.load();
        uint64_t elapsed = last > 0 ? (GetTickCount64() - last) / 1000 : 0;
        uint64_t remain = elapsed < interval ? interval - elapsed : 0;
        StringCchPrintfW(g_nid.szTip, ARRAYSIZE(g_nid.szTip), L"AntiAFK-RBX • Running • next %02llu:%02llu", remain / 60, remain % 60);
    } else {
        StringCchPrintfW(g_nid.szTip, ARRAYSIZE(g_nid.szTip), L"AntiAFK-RBX • Stopped");
    }
    HICON oldIcon = g_nid.hIcon;
    g_nid.hIcon = CreateCustomIcon();
    bool ok = Shell_NotifyIcon(NIM_ADD, &g_nid) != FALSE;
    if (ok) {
        if (oldIcon && oldIcon != g_nid.hIcon) DestroyIcon(oldIcon);
    } else {
        if (g_nid.hIcon && g_nid.hIcon != oldIcon) DestroyIcon(g_nid.hIcon);
        g_nid.hIcon = oldIcon;
    }
    return ok;
}
// ==========

bool CheckForUpdates(bool showNotification = true)
{
    bool updateFound = false;
    DWORD timeoutMs = 5000;
    g_updateFound = false;
    g_updateCheckFailed = false;
    g_updateServerVersion = 0;
    HINTERNET hInternet = InternetOpen(L"AntiAFK-RBX/4.0", INTERNET_OPEN_TYPE_PRECONFIG, NULL, NULL, 0);
    if (!hInternet) {
        g_updateCheckFailed = true;
        return false;
    }

    InternetSetOption(hInternet, INTERNET_OPTION_CONNECT_TIMEOUT, &timeoutMs, sizeof(timeoutMs));
    InternetSetOption(hInternet, INTERNET_OPTION_SEND_TIMEOUT, &timeoutMs, sizeof(timeoutMs));
    InternetSetOption(hInternet, INTERNET_OPTION_RECEIVE_TIMEOUT, &timeoutMs, sizeof(timeoutMs));

    HINTERNET hConnect = InternetOpenUrl(hInternet, GetVersionCheckUrl(), NULL, 0, INTERNET_FLAG_RELOAD | INTERNET_FLAG_SECURE | INTERNET_FLAG_NO_UI, 0);
    if (!hConnect) {
        g_updateCheckFailed = true;
        InternetCloseHandle(hInternet);
        return false;
    }

    InternetSetOption(hConnect, INTERNET_OPTION_CONNECT_TIMEOUT, &timeoutMs, sizeof(timeoutMs));
    InternetSetOption(hConnect, INTERNET_OPTION_SEND_TIMEOUT, &timeoutMs, sizeof(timeoutMs));
    InternetSetOption(hConnect, INTERNET_OPTION_RECEIVE_TIMEOUT, &timeoutMs, sizeof(timeoutMs));

    char buffer[256] = { 0 };
    DWORD bytesRead = 0;
    std::string versionData;
    while (InternetReadFile(hConnect, buffer, sizeof(buffer) - 1, &bytesRead) && bytesRead > 0)
    {
        versionData.append(buffer, bytesRead);
        bytesRead = 0;
        if (versionData.size() >= 64) break;
    }
    if (!versionData.empty())
    {
        try {
            int serverVersion = std::stoi(versionData);
            if (serverVersion > currentVersion) {
                updateFound = true;
                g_updateFound = true;
                g_updateServerVersion = serverVersion;
                if (showNotification) {
                    wchar_t msg[128];
                    swprintf_s(msg, L"New version available! Download at: https://github.com/Agzes/AntiAFK-RBX");
                    ShowTrayNotification(L"AntiAFK-RBX • Update Available", msg);
                }
                if (g_hwnd) {
                    QueueRefreshTrayMenu(g_isAfkStarted.load());
                }
            }
        }
        catch (const std::invalid_argument&) {
            g_updateCheckFailed = true;
        }
        catch (const std::out_of_range&) {
            g_updateCheckFailed = true;
        }
    }
    else
    {
        g_updateCheckFailed = true;
    }

    InternetCloseHandle(hConnect);
    InternetCloseHandle(hInternet);

    if (g_hMainUiWnd && IsWindow(g_hMainUiWnd))
    {
        InvalidateRect(g_hMainUiWnd, NULL, FALSE);
    }

    return updateFound;
}

