        pData->navItems.push_back({ L"General", L"\xE80F", {0, 0, 0, 0}, 0.0f });
        pData->navItems.push_back({ L"Auto+Utils", L"\xE945", {0, 0, 0, 0}, 0.0f });
        pData->navItems.push_back({ L"Misc", L"\xE90F", {0, 0, 0, 0}, 0.0f });
        pData->navItems.push_back({ L"Advanced", L"\xE713", {0, 0, 0, 0}, 0.0f });
        pData->navItems.push_back({ L"Statistics", L"\xE9D2", {0, 0, 0, 0}, 0.0f });
        pData->navItems.push_back({ L"Webhook", L"\xE8BD", {0, 0, 0, 0}, 0.0f });


        pData->hCursorHand = LoadCursor(NULL, IDC_HAND);
        pData->hCursorArrow = LoadCursor(NULL, IDC_ARROW);
        pData->hCursorText = LoadCursor(NULL, IDC_IBEAM);

        pData->hIcon = (HICON)LoadImage(g_hInst, MAKEINTRESOURCE(IDI_TRAY_OFF), IMAGE_ICON, 16, 16, LR_DEFAULTCOLOR);
        pData->hSplashLogoIcon = (HICON)LoadImage(g_hInst, MAKEINTRESOURCE(IDI_MAIN), IMAGE_ICON, 256, 256, LR_DEFAULTCOLOR);
        if (pData->hSplashLogoIcon) {
            pData->pSplashLogoBitmap = Bitmap::FromHICON(pData->hSplashLogoIcon);
        }
        pData->startupOverlayVisible = g_useMainUiStartupOverlay.exchange(false);
        pData->startupOverlayAlpha = pData->startupOverlayVisible ? 1.0f : 0.0f;
        pData->startupOverlayFadeDirection = 0;
        pData->startupOverlayShownTick = pData->startupOverlayVisible ? GetTickCount64() : 0;
        pData->badgeRevealAnim = 1.0f;
        pData->badgeRevealDirection = 0;

        pData->multiInstanceAnim = g_multiSupport.load() ? 1.0f : 0.0f;
        pData->mutexStatusAnim = g_multiSupport.load() ? 1.0f : 0.0f;
        pData->autoUpdateAnim = g_autoUpdate.load() ? 1.0f : 0.0f;
