        pData->autoReconnectAnim = g_autoReconnect.load() ? 1.0f : 0.0f;
        pData->autoResetAnim = g_autoReset.load() ? 1.0f : 0.0f;
        pData->autoHideAnim = g_autoHideRoblox.load() ? 1.0f : 0.0f;
